    for(const e of state.enemies){drawPlane(c,e.x,e.y,e.scale,e.angle,e.type===2?'#77745b':'#9b634f','#e3c898',e.type);if(e.hp<e.max){c.fillStyle='#142a2a88';c.fillRect(e.x-13,e.y-25,26,2);c.fillStyle='#ec8859';c.fillRect(e.x-13,e.y-25,26*e.hp/e.max,2)}}
