  c.fillStyle='#d2d7c3';
  for(let i=0;i<26;i++){const x=(i*173)%w,y=hz+((i*71+performance.now()*.018)%(h-hz));c.fillRect(x,y,18,1)}
  for(const island of state.islands){c.fillStyle='#315d56';c.beginPath();c.ellipse(island.x,island.y,36*island.s,13*island.s,0,0,Math.PI*2);c.fill()}
